INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können IPv4-Adressen manuell zugewiesen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Manuelle Zuweisung ist möglich, aber aufwendig"}, {"text": "Nein", "correct": false, "because": "Manuelle Zuweisung ist erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist DHCP die einzige Methode zur Zuweisung von IPv4-Adressen?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Zuweisung ist ebenfalls möglich"}, {"text": "Ja", "correct": false, "because": "Es gibt Alternativen wie statische Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IPv4-Adresse automatisch ohne DHCP zugewiesen werden?', 2, '[{"text": "Ja", "correct": true, "because": "APIPA (169.254.x.x) ist eine Alternative"}, {"text": "Nein", "correct": false, "because": "APIPA existiert als Fallback"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Geräte in einem Netzwerk die gleiche Adresszuweisungsmethode nutzen?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle und automatische Methoden können gemischt werden"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Adresszuweisung per DHCP in kleinen Netzwerken zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Netzwerke können auch manuell konfiguriert werden"}, {"text": "Ja", "correct": false, "because": "DHCP ist optional"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird am häufigsten für die automatische IPv4-Adresszuweisung verwendet?', 2, '[{"text": "DHCP", "correct": true, "because": "Dynamic Host Configuration Protocol ist Standard"}, {"text": "SLAAC", "correct": false, "because": "Das ist für IPv6"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein DHCP-Server in einem Netzwerk ausfällt?', 3, '[{"text": "Geräte können APIPA-Adressen (169.254.x.x) nutzen", "correct": true, "because": "APIPA ist ein Fallback-Mechanismus"}, {"text": "Alle Geräte verlieren ihre IP-Adressen sofort", "correct": false, "because": "Bestehende leases bleiben temporär"}, {"text": "Manuelle Zuweisung ist unmöglich", "correct": false, "because": "Manuell bleibt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wird einem Gerät automatisch zugewiesen, wenn kein DHCP verfügbar ist?', 2, '[{"text": "169.254.0.1", "correct": true, "because": "APIPA-Bereich wird genutzt"}, {"text": "192.168.1.1", "correct": false, "because": "Typisch für DHCP, nicht Fallback"}, {"text": "0.0.0.0", "correct": false, "because": "Keine gültige Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Begriff beschreibt die zeitlich begrenzte Zuweisung einer IPv4-Adresse durch DHCP?', 2, '[{"text": "Lease", "correct": true, "because": "DHCP vergibt Adressen temporär (Lease Time)"}, {"text": "Static", "correct": false, "because": "Das ist dauerhaft"}, {"text": "Pool", "correct": false, "because": "Bezieht sich auf verfügbare Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist für die DHCP-Adresszuweisung verantwortlich?', 2, '[{"text": "DHCP-Server", "correct": true, "because": "Er verteilt die Adressen"}, {"text": "Router", "correct": false, "because": "Nur wenn er DHCP-Server ist"}, {"text": "Switch", "correct": false, "because": "Switch leitet nur Daten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gibt es für die IPv4-Adresszuweisung?', 4, '[{"text": "Manuelle Zuweisung", "correct": true, "because": "Statische Adressen sind möglich"}, {"text": "DHCP", "correct": true, "because": "Automatische Zuweisung"}, {"text": "APIPA", "correct": true, "because": "Fallback bei DHCP-Ausfall"}, {"text": "SLAAC", "correct": false, "because": "Nur für IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen vergibt ein DHCP-Server bei der Adresszuweisung?', 3, '[{"text": "IP-Adresse", "correct": true, "because": "Hauptfunktion von DHCP"}, {"text": "Subnetzmaske", "correct": true, "because": "Wird mitgeliefert"}, {"text": "Standard-Gateway", "correct": true, "because": "Für Netzwerkzugriff nötig"}, {"text": "Hardware-Typ", "correct": false, "because": "Nicht Teil der Zuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sind Vorteile der DHCP-Adresszuweisung?', 4, '[{"text": "Geringerer Verwaltungsaufwand", "correct": true, "because": "Automatisierung spart Zeit"}, {"text": "Vermeidung von Adresskonflikten", "correct": true, "because": "DHCP prüft Verfügbarkeit"}, {"text": "Höhere Sicherheit", "correct": false, "because": "Sicherheit ist nicht direkt betroffen"}, {"text": "Flexibilität bei neuen Geräten", "correct": true, "because": "Automatische Integration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der manuellen IPv4-Adresszuweisung auftreten?', 3, '[{"text": "Adresskonflikte", "correct": true, "because": "Doppelte Vergabe möglich"}, {"text": "Hoher Verwaltungsaufwand", "correct": true, "because": "Jede Adresse muss geprüft werden"}, {"text": "Langsame Internetverbindung", "correct": false, "because": "Nicht direkt verknüpft"}, {"text": "Kompatibilitätsprobleme", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur DHCP-Adresszuweisung?', 3, '[{"text": "Client sendet DHCP Discover", "correct": true, "because": "Erster Schritt im Prozess"}, {"text": "Server antwortet mit DHCP Offer", "correct": true, "because": "Angebot einer Adresse"}, {"text": "Client wählt manuell eine Adresse", "correct": false, "because": "Automatisch durch Server"}, {"text": "Lease wird bestätigt", "correct": true, "because": "Abschluss der Zuweisung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) DHCP vergibt IPv4-Adressen automatisch. b) Manuelle Zuweisung ist unmöglich, wenn DHCP aktiv ist.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCP ist automatisch, manuell bleibt möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) APIPA tritt bei DHCP-Ausfall ein. b) APIPA-Adressen sind weltweit routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "APIPA ist lokal, nicht routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DHCP-Leases sind zeitlich begrenzt. b) Statische Adressen ändern sich regelmäßig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leases sind temporär, statische Adressen fix"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein DHCP-Server kann mehrere Netzwerke bedienen. b) APIPA ersetzt DHCP vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCP kann flexibel sein, APIPA ist nur Fallback"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Manuelle Adresszuweisung vermeidet Konflikte automatisch. b) DHCP prüft die Verfügbarkeit von Adressen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Manuell riskiert Konflikte, DHCP prüft"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

